"""Schema-validated finite-bag query execution for README.md's language."""


def _shape(value, keys, description):
    if not isinstance(value, dict) or set(value) != set(keys):
        raise ValueError(description + ' shape')


def _field(name, columns):
    if not isinstance(name, str) or name not in columns:
        raise ValueError('unknown field: ' + repr(name))
    return columns[name]


def _compatible(a, b):
    # A literal-null output has no concrete type and can unify with either.
    return a == b or 'null' in (a, b)


def _expression_type(expr, columns):
    if not isinstance(expr, dict) or len(expr) != 1:
        raise ValueError('expression shape')
    op, arg = next(iter(expr.items()))
    if op == 'col':
        return _field(arg, columns)
    if op == 'lit':
        if arg is None:
            return 'null'
        if type(arg) is int:
            return 'int'
        if type(arg) is str:
            return 'str'
        raise ValueError('literal type')
    if op in ('add', 'sub'):
        if not isinstance(arg, list) or len(arg) != 2:
            raise ValueError('arithmetic arity')
        types = [_expression_type(e, columns) for e in arg]
        if any(t not in ('int', 'null') for t in types):
            raise ValueError('integer arithmetic')
        return 'int'
    raise ValueError('unknown expression')


def _predicate_type(pred, columns):
    if not isinstance(pred, dict) or len(pred) != 1:
        raise ValueError('predicate shape')
    op, arg = next(iter(pred.items()))
    if op == 'is_null':
        _expression_type(arg, columns)
    elif op == 'not':
        _predicate_type(arg, columns)
    elif op in ('and', 'or'):
        if not isinstance(arg, list) or len(arg) < 2:
            raise ValueError('boolean arity')
        for predicate in arg:
            _predicate_type(predicate, columns)
    elif op in ('eq', 'ne', 'lt', 'le', 'gt', 'ge'):
        if not isinstance(arg, list) or len(arg) != 2:
            raise ValueError('comparison arity')
        a, b = [_expression_type(e, columns) for e in arg]
        if not _compatible(a, b):
            raise ValueError('comparison types')
    else:
        raise ValueError('unknown predicate')


def _validate_tables(tables):
    if not isinstance(tables, dict):
        raise ValueError('tables shape')
    for name, table in tables.items():
        if not isinstance(name, str) or not name:
            raise ValueError('table name')
        _shape(table, ('columns', 'rows'), 'table')
        if not isinstance(table['columns'], dict) or not isinstance(table['rows'], list):
            raise ValueError('table shape')
        for name, kind in table['columns'].items():
            if (not isinstance(name, str) or not name or '.' in name
                    or kind not in ('int', 'str')):
                raise ValueError('column schema')
        for row in table['rows']:
            _shape(row, table['columns'], 'row')
            for name, value in row.items():
                expected = int if table['columns'][name] == 'int' else str
                if value is not None and type(value) is not expected:
                    raise ValueError('row type')


def _plan_schema(tables, plan, schemas):
    if not isinstance(plan, dict) or not isinstance(plan.get('op'), str):
        raise ValueError('plan shape')
    op = plan['op']
    if op == 'scan':
        _shape(plan, ('op', 'table', 'as'), 'scan')
        alias = plan['as']
        if not isinstance(alias, str) or not alias or '.' in alias:
            raise ValueError('scan alias')
        if not isinstance(plan['table'], str) or plan['table'] not in tables:
            raise ValueError('unknown table')
        columns = {alias + '.' + name: kind
                   for name, kind in tables[plan['table']]['columns'].items()}
    elif op in ('filter', 'project', 'group'):
        keys = {'filter': ('op', 'input', 'predicate'),
                'project': ('op', 'input', 'fields'),
                'group': ('op', 'input', 'keys', 'aggregates')}[op]
        _shape(plan, keys, op)
        source = _plan_schema(tables, plan['input'], schemas)
        if op == 'filter':
            _predicate_type(plan['predicate'], source)
            columns = source
        elif op == 'project':
            if not isinstance(plan['fields'], dict):
                raise ValueError('project fields')
            columns = {}
            for name, expr in plan['fields'].items():
                if not isinstance(name, str):
                    raise ValueError('output name')
                columns[name] = _expression_type(expr, source)
        else:
            if not isinstance(plan['keys'], list) or not isinstance(plan['aggregates'], dict):
                raise ValueError('group shape')
            columns = {}
            for name in plan['keys']:
                kind = _field(name, source)
                if name in columns:
                    raise ValueError('duplicate group key')
                columns[name] = kind
            for name, agg in plan['aggregates'].items():
                if not isinstance(name, str) or name in columns:
                    raise ValueError('aggregate output name')
                if not isinstance(agg, dict):
                    raise ValueError('aggregate shape')
                fn = agg.get('fn')
                if fn == 'count_all':
                    _shape(agg, ('fn',), 'count_all')
                elif fn in ('count', 'sum'):
                    _shape(agg, ('fn', 'expr'), 'aggregate')
                    kind = _expression_type(agg['expr'], source)
                    if fn == 'sum' and kind not in ('int', 'null'):
                        raise ValueError('sum integer')
                else:
                    raise ValueError('aggregate function')
                columns[name] = 'int'
    elif op == 'join':
        _shape(plan, ('op', 'kind', 'left', 'right', 'left_on', 'right_on'), 'join')
        if plan['kind'] not in ('inner', 'left'):
            raise ValueError('join kind')
        left = _plan_schema(tables, plan['left'], schemas)
        right = _plan_schema(tables, plan['right'], schemas)
        if left.keys() & right.keys():
            raise ValueError('overlapping join fields')
        a = _field(plan['left_on'], left)
        b = _field(plan['right_on'], right)
        if not _compatible(a, b):
            raise ValueError('join key types')
        columns = {**left, **right}
    else:
        raise ValueError('unknown plan operator')
    schemas[id(plan)] = columns
    return columns


def validate_request(request):
    _shape(request, ('tables', 'plan'), 'request')
    _validate_tables(request['tables'])
    _plan_schema(request['tables'], request['plan'], {})
    return request


def scalar(expr, row):
    """Evaluate one scalar expression; execute validates its schema first."""
    if not isinstance(expr, dict) or len(expr) != 1:
        raise ValueError('expression shape')
    op, arg = next(iter(expr.items()))
    if op == 'col':
        return row[arg]
    if op == 'lit':
        if arg is not None and type(arg) not in (str, int):
            raise ValueError('literal type')
        return arg
    if op in ('add', 'sub'):
        if not isinstance(arg, list) or len(arg) != 2:
            raise ValueError('arithmetic arity')
        a, b = [scalar(e, row) for e in arg]
        if any(v is not None and type(v) is not int for v in (a, b)):
            raise ValueError('integer arithmetic')
        if a is None or b is None:
            return None
        return a + b if op == 'add' else a - b
    raise ValueError('unknown expression')


def truth(pred, row):
    """Evaluate a predicate as True, False, or None (SQL unknown)."""
    if not isinstance(pred, dict) or len(pred) != 1:
        raise ValueError('predicate shape')
    op, arg = next(iter(pred.items()))
    if op == 'is_null':
        return scalar(arg, row) is None
    if op == 'not':
        value = truth(arg, row)
        return None if value is None else not value
    if op in ('and', 'or'):
        if not isinstance(arg, list) or len(arg) < 2:
            raise ValueError('boolean arity')
        values = [truth(p, row) for p in arg]
        if op == 'and':
            return False if False in values else (None if None in values else True)
        return True if True in values else (None if None in values else False)
    if op not in ('eq', 'ne', 'lt', 'le', 'gt', 'ge') or not isinstance(arg, list) or len(arg) != 2:
        raise ValueError('comparison')
    a, b = [scalar(e, row) for e in arg]
    if a is None or b is None:
        return None
    if type(a) is not type(b) or type(a) not in (int, str):
        raise ValueError('comparison types')
    if op == 'eq':
        return a == b
    if op == 'ne':
        return a != b
    if op == 'lt':
        return a < b
    if op == 'le':
        return a <= b
    if op == 'gt':
        return a > b
    return a >= b


def execute(tables, plan):
    """Return (rows, actual nested-loop candidate-pair comparisons)."""
    _validate_tables(tables)
    schemas = {}
    _plan_schema(tables, plan, schemas)

    def walk(node):
        op = node['op']
        if op == 'scan':
            return [{node['as'] + '.' + k: v for k, v in row.items()}
                    for row in tables[node['table']]['rows']], 0
        if op == 'join':
            left, ln = walk(node['left'])
            right, rn = walk(node['right'])
            out, comparisons = [], ln + rn
            null_right = {k: None for k in schemas[id(node['right'])]}
            for a in left:
                matched = False
                for b in right:
                    comparisons += 1
                    x, y = a[node['left_on']], b[node['right_on']]
                    if x is not None and y is not None and x == y:
                        out.append({**a, **b})
                        matched = True
                if not matched and node['kind'] == 'left':
                    out.append({**a, **null_right})
            return out, comparisons
        rows, comparisons = walk(node['input'])
        if op == 'filter':
            return [row for row in rows if truth(node['predicate'], row) is True], comparisons
        if op == 'project':
            return [{name: scalar(expr, row) for name, expr in node['fields'].items()}
                    for row in rows], comparisons
        groups = {}
        for row in rows:
            groups.setdefault(tuple(row[k] for k in node['keys']), []).append(row)
        if not node['keys'] and not rows:
            groups[()] = []
        out = []
        for key, members in groups.items():
            row = dict(zip(node['keys'], key))
            for name, agg in node['aggregates'].items():
                if agg['fn'] == 'count_all':
                    row[name] = len(members)
                else:
                    values = [scalar(agg['expr'], member) for member in members]
                    values = [v for v in values if v is not None]
                    row[name] = (len(values) if agg['fn'] == 'count'
                                 else sum(values) if values else None)
            out.append(row)
        return out, comparisons

    return walk(plan)

