"""Conservative, table-independent predicate pushdown for INNER JOINs."""
import copy


def _references(value):
    if isinstance(value, dict):
        if set(value) == {'col'}:
            return {value['col']}
        return set().union(*(_references(v) for v in value.values()))
    if isinstance(value, list):
        return set().union(*(_references(v) for v in value))
    return set()


def _may_produce(plan, field):
    """Bound possible ownership from aliases or explicit outputs.

    Scan fields have exactly one dot. Without table schemas an alias only
    gives possible ownership: two disjoint input schemas can share an alias.
    Project/group output fields are explicit, including any dotted names.
    """
    op = plan['op']
    if op == 'scan':
        prefix = plan['as'] + '.'
        return (field.startswith(prefix) and bool(field[len(prefix):])
                and '.' not in field[len(prefix):])
    if op == 'project':
        return field in plan['fields']
    if op == 'group':
        return field in plan['keys'] or field in plan['aggregates']
    if op == 'filter':
        return _may_produce(plan['input'], field)
    return _may_produce(plan['left'], field) or _may_produce(plan['right'], field)


def _conjuncts(predicate):
    # Splitting AND preserves which rows are true under three-valued logic.
    # OR and NOT stay intact, including conjunctions nested inside them.
    if set(predicate) == {'and'}:
        return [p for child in predicate['and'] for p in _conjuncts(child)]
    return [predicate]


def _conjunction(predicates):
    return predicates[0] if len(predicates) == 1 else {'and': predicates}


def _push(source, predicates):
    if source['op'] == 'filter':
        return _push(source['input'], _conjuncts(source['predicate']) + predicates)
    if source['op'] == 'join' and source['kind'] == 'inner':
        left, right, remaining = [], [], []
        for predicate in predicates:
            fields = _references(predicate)
            if all(_may_produce(source['left'], field)
                   and not _may_produce(source['right'], field) for field in fields):
                left.append(predicate)
            elif all(_may_produce(source['right'], field)
                     and not _may_produce(source['left'], field) for field in fields):
                right.append(predicate)
            else:
                remaining.append(predicate)
        if left:
            source['left'] = _push(source['left'], left)
        if right:
            source['right'] = _push(source['right'], right)
        predicates = remaining
    # LEFT JOIN, GROUP and PROJECT are deliberate pushdown barriers.
    if predicates:
        return {'op': 'filter', 'input': source,
                'predicate': _conjunction(predicates)}
    return source


def optimize(plan):
    """Return an independent plan without mutating the input.

    Validate the original plan before optimizing so invalid source expressions
    cannot disappear as a consequence of rewriting or filtering empty data.
    """
    def visit(node):
        # Rebuild each occurrence, even if a Python caller shared a subtree.
        node = dict(node)
        op = node['op']
        if op == 'join':
            node['left'] = visit(node['left'])
            node['right'] = visit(node['right'])
        elif op in ('filter', 'project', 'group'):
            node['input'] = visit(node['input'])
            if op == 'filter':
                return _push(node['input'], _conjuncts(node['predicate']))
        return node

    return visit(copy.deepcopy(plan))

