"""Documented JSON query CLI;ordinary errors return exit2 and no result."""
import argparse,json,sys
from engine import validate_request,execute
from optimizer import optimize

def unique(pairs):
 d={}
 for k,v in pairs:
  if k in d:raise ValueError('duplicate JSON key:'+k)
  d[k]=v
 return d

def invalid_constant(value):
 raise ValueError('invalid JSON constant:'+value)

def main():
 p=argparse.ArgumentParser();p.add_argument('command',choices=['run']);p.add_argument('--request',required=True);p.add_argument('--optimize',action='store_true');args=p.parse_args()
 try:
  # The contract uses exact integers, including values beyond Python's default
  # decimal conversion limit, and JSON never permits NaN or Infinity.
  if hasattr(sys,'set_int_max_str_digits'):sys.set_int_max_str_digits(0)
  with open(args.request,encoding='utf-8') as f:r=validate_request(json.load(f,object_pairs_hook=unique,parse_constant=invalid_constant))
  plan=optimize(r['plan']) if args.optimize else r['plan'];rows,n=execute(r['tables'],plan);print(json.dumps({'rows':rows,'join_comparisons':n,'optimized_plan':plan},sort_keys=True,allow_nan=False))
 except Exception as e:print(type(e).__name__+':'+str(e),file=sys.stderr);raise SystemExit(2)
if __name__=='__main__':main()

